<?php
require_once __DIR__ . '/_auth.php';
require_once __DIR__ . '/../../includes/work_tracker.php';
$id=(int)($_GET['id']??0);$job=wt_job($pdo,$id);$tasks=wt_job_tasks($pdo,$id,false);
$q=$pdo->prepare("SELECT * FROM work_task_photos WHERE job_id=? ORDER BY task_id,photo_type,created_at,id");$q->execute([$id]);$by=[];foreach($q->fetchAll(PDO::FETCH_ASSOC) as $p)$by[(int)$p['task_id']][$p['photo_type']][]=$p;
$token=$job['public_token']??'';
?><!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Task photos</title><style>body{font-family:system-ui;background:#f4f6f8;color:#17202a}.wrap{max-width:1000px;margin:auto;padding:20px}.card{background:#fff;border-radius:14px;padding:16px;margin:12px 0;box-shadow:0 2px 10px #0001}.cols{display:grid;grid-template-columns:1fr 1fr;gap:14px}.photo{max-width:180px;max-height:140px;border-radius:8px;border:1px solid #ccd}.muted{color:#66717c;font-size:13px}.btn{background:#17202a;color:#fff;border:0;border-radius:9px;padding:10px 13px;font-weight:800}input,textarea{width:100%;box-sizing:border-box;margin:5px 0;padding:9px}@media(max-width:700px){.cols{grid-template-columns:1fr}}</style><div class="wrap"><p><a href="manage_job.php?id=<?=$id?>">← Manage job</a></p><h1>Task photos — <?=wt_html($job['customer_name'])?></h1><p class="muted">Original before/after images are preserved. Future social-media collages should use copies, never alter these originals.</p><?php foreach($tasks as $t):?><div class="card" id="task-<?=$t['id']?>"><h2><?=wt_html($t['title'])?></h2><div class="cols"><?php foreach(['before'=>'Before','after'=>'After'] as $type=>$label):?><div><h3><?=$label?></h3><?php foreach(($by[(int)$t['id']][$type]??[]) as $p):?><div style="margin:8px 0"><img class="photo" src="../../work/task_photo.php?id=<?=$p['id']?>&t=<?=urlencode($token)?>"><div class="muted">Uploaded by <?=wt_html($p['uploader_type'])?> · <?=wt_html(date('j M Y, g:i a',strtotime($p['created_at'])))?></div><?php if($p['note']):?><div><?=wt_html($p['note'])?></div><?php endif;?></div><?php endforeach;?><form method="post" action="../../api/work/upload_task_photo_admin.php" enctype="multipart/form-data"><input type="hidden" name="job_id" value="<?=$id?>"><input type="hidden" name="task_id" value="<?=$t['id']?>"><input type="hidden" name="photo_type" value="<?=$type?>"><input type="file" name="photos[]" accept="image/jpeg,image/png,image/webp" multiple required><input name="note" placeholder="Optional note"><button class="btn">ADD <?=$label?> PHOTO</button></form></div><?php endforeach;?></div></div><?php endforeach;?></div>
